rule.definition:
a!localVariables(
  local!currentYear:year(today()),
  local!yearToDisplay:if(
    month(today()) < #"_a-0000e6b8-3009-8000-9bf7-011c48011c48_3440558",
    local!currentYear,
    local!currentYear + 1
  )-6,
  local!datesToGenerate:#"_a-0000e6bc-0703-8000-9bf8-011c48011c48_3521276"+6,
  {
    a!flatten(
      #"SYSTEM_SYSRULES_forEach"(
        items: enumerate(local!datesToGenerate),
        expression: {
          year:if(
            fv!isLast,
            concat(tostring(date(local!yearToDisplay + fv!item,#"_a-0000e6b8-3009-8000-9bf7-011c48011c48_3440558",#"_a-0000e6bc-0703-8000-9bf8-011c48011c48_3521308"))," " ,#"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4234042"),
            concat(tostring(date(local!yearToDisplay + fv!item,#"_a-0000e6b8-3009-8000-9bf7-011c48011c48_3440558",#"_a-0000e6bc-0703-8000-9bf8-011c48011c48_3521308")))
          ),
          display:if(
            fv!isLast,
            concat(
              date(local!yearToDisplay + fv!item,#"_a-0000e6b8-3009-8000-9bf7-011c48011c48_3440558",#"_a-0000e6bc-0703-8000-9bf8-011c48011c48_3521308"),
              " (FY", 
              right(local!yearToDisplay + fv!item + 1 , 2),
              ")",
              " ",
              #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4234042"
            ),
            concat(
              date(local!yearToDisplay + fv!item,#"_a-0000e6b8-3009-8000-9bf7-011c48011c48_3440558",#"_a-0000e6bc-0703-8000-9bf8-011c48011c48_3521308"),
              " (FY", 
              right(local!yearToDisplay + fv!item + 1 , 2),
              ")"
            )
          )
        }
      )
    ),
    {
      year: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3197185",
      display: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3197185"
    }
  }

)
